#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DType {
    /// Kind code: 'b', 'i', 'u', 'f', 'c', or 'O'
    pub kind: char,
    /// Promotion precedence (larger means more general)
    pub precedence: i32,
}

/// Task 1:
/// Given a non-empty collection of dtypes, return one of the elements with
/// maximum precedence (ties: first encountered).
pub fn find_max_precedence_type(types: Vec<DType>) -> DType {
    assert!(!types.is_empty(), "types must be non-empty");
    types
        .into_iter()
        .max_by_key(|dt| dt.precedence)
        .expect("non-empty")
}

/// Task 2:
/// Determine common dtype based on maxima of array/scalar collections.
/// Returns None only if both inputs are empty.
pub fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    match (array_types.is_empty(), scalar_types.is_empty()) {
        (true, true) => None,
        (false, true) => Some(find_max_precedence_type(array_types)),
        (true, false) => Some(find_max_precedence_type(scalar_types)),
        (false, false) => {
            let array_max = find_max_precedence_type(array_types);
            let scalar_max = find_max_precedence_type(scalar_types);

            if array_max.kind == scalar_max.kind {
                Some(array_max)
            } else {
                Some(scalar_max)
            }
        }
    }
}